// Types that read and write themselves: a format's records and packed flag fields, read in one call
// (`try reader.read(LocalFileHeader.self)`). Written by hand, or generated by `BytesMacros`' `@BinaryRecord`
// and `@BitFields`.

/// A value read from bytes by its own initializer.
///
/// ```swift
/// struct Version: BinaryParsable {
///     var major: UInt8, minor: UInt8
///     init<Mode: BytesCursorMode>(parsing reader: inout GenericBytesReader<Mode>) throws(BytesError) {
///         major = try reader.read(UInt8.self)
///         minor = try reader.read(UInt8.self)
///     }
/// }
/// let version = try reader.read(Version.self)
/// ```
///
/// Generic over the cursor's mode, so one parser serves every kind of reader; each use is specialized.
///
/// The `@BinaryRecord` and `@BitFields` macros (the `BytesMacros` product) generate this conformance, with
/// ``BinaryWritable`` and ``FixedSizeBinary``, from a struct's properties.
public protocol BinaryParsable {
    /// Reads a value, consuming its bytes.
    ///
    /// - Parameter reader: The cursor, positioned at the value.
    /// - Throws: ``BytesError`` if the bytes aren't a valid value; what's consumed then is up to the type
    ///   (records generated by `@BinaryRecord` consume nothing).
    init<Mode: BytesCursorMode>(parsing reader: inout GenericBytesReader<Mode>) throws(BytesError)
}

/// A value that writes its own bytes.
public protocol BinaryWritable {
    /// Writes the value.
    ///
    /// - Parameter writer: The cursor to write at.
    /// - Throws: ``BytesError/insufficientCapacity`` if there isn't room.
    func write<Mode: BytesCursorMode>(to writer: inout GenericBytesWriter<Mode>) throws(BytesError)
}

/// A value that always takes the same number of bytes: a record of fixed fields, or packed flags. Records
/// made of them know their size as a constant, so they're read with one bounds check.
public protocol FixedSizeBinary {
    /// The value's size in bytes.
    static var byteCount: Int { get }
}

/// A value read from bytes by its own initializer, its integers in the cursor's byte order: for formats whose
/// byte order is chosen at run time (ELF and PCAPNG name it in their first bytes), so one declaration serves
/// both orders, each compiled separately.
///
/// ```swift
/// @BinaryRecord                     // no byte order: the cursor's
/// struct SectionHeader {
///     @Field(Byte4.self) var name: UInt32
///     @Field(Byte4.self) var type: SectionType
///     …
/// }
///
/// func parse<Mode: ByteOrderedCursorMode>(_ reader: inout GenericBytesReader<Mode>) throws(BytesError) {
///     let header = try reader.read(SectionHeader.self)
/// }
/// switch order {
/// case .littleEndian: var reader = LittleEndianBytesReader(data); try parse(&reader)
/// case .bigEndian: var reader = BigEndianBytesReader(data); try parse(&reader)
/// }
/// ```
///
/// Only byte-ordered cursors (``BigEndianBytesReader``, ``LittleEndianBytesReader``) read these: from any other
/// cursor the order would be unknown, which is a compile error rather than a guess. `@BinaryRecord` without a
/// byte order, and `@BitFields` over `UInt16`, `UInt32`, or `UInt64` without one, generate this conformance.
public protocol ByteOrderedParsable {
    /// Reads a value in the cursor's byte order, consuming its bytes.
    ///
    /// - Parameter reader: The cursor, positioned at the value.
    /// - Throws: ``BytesError`` if the bytes aren't a valid value; what's consumed then is up to the type
    ///   (records generated by `@BinaryRecord` consume nothing).
    init<Mode: ByteOrderedCursorMode>(parsing reader: inout GenericBytesReader<Mode>) throws(BytesError)
}

/// A value that writes its own bytes, its integers in the writer's byte order: the counterpart of
/// ``ByteOrderedParsable``.
public protocol ByteOrderedWritable {
    /// Writes the value in the writer's byte order.
    ///
    /// - Parameter writer: The cursor to write at.
    /// - Throws: ``BytesError/insufficientCapacity`` if there isn't room.
    func write<Mode: ByteOrderedCursorMode>(to writer: inout GenericBytesWriter<Mode>) throws(BytesError)
}

/// Bytes a record skips: padding, or space a format leaves unused, read without looking at it and written as
/// zeros. A `@BinaryRecord` field of this type takes `Group.byteCount` bytes and stores nothing.
///
/// ```swift
/// @BinaryRecord(.bigEndian)
/// struct Identification {
///     @Field(Byte4.self, expecting: 0x7F45_4C46) var magic: UInt32
///     @Field(Byte.self) var fileClass: FileClass
///     …
///     var padding: Padding<Byte7>           // ignored when read
/// }
/// ```
///
/// For bytes that must be zero, use ``Reserved``.
@frozen
public struct Padding<Group: ByteGroup>: BinaryParsable, BinaryWritable, FixedSizeBinary, Hashable, Sendable {
    /// Padding: there's nothing to say about it.
    @inlinable @inline(__always)
    public init() {}

    /// The padding's size: `Group.byteCount`.
    @inlinable @inline(__always)
    public static var byteCount: Int { Group.byteCount }

    /// Skips the padding.
    ///
    /// - Parameter reader: The cursor, positioned at the padding.
    /// - Throws: ``BytesError/insufficientData`` if fewer bytes remain, consuming nothing.
    @inlinable @inline(__always)
    public init<Mode: BytesCursorMode>(parsing reader: inout GenericBytesReader<Mode>) throws(BytesError) {
        try reader.skip(byteCount: Group.byteCount)
    }

    /// Writes the padding as zeros.
    ///
    /// - Parameter writer: The cursor to write at.
    /// - Throws: ``BytesError/insufficientCapacity`` if there isn't room.
    @inlinable @inline(__always)
    public func write<Mode: BytesCursorMode>(to writer: inout GenericBytesWriter<Mode>) throws(BytesError) {
        try writer.write(Group.Integer.zero, as: Group.self, .littleEndian)
    }
}

/// Reserved bytes, which must be zero: checked when read and written as zeros. A `@BinaryRecord` field of this
/// type takes `Group.byteCount` bytes and stores nothing.
///
/// ```swift
/// var reserved: Reserved<Byte2>            // throws if either byte isn't 0
/// ```
///
/// For bytes whose value doesn't matter, use ``Padding``; for reserved bits within a field, `@BitFields`'
/// `reserved:` ranges.
@frozen
public struct Reserved<Group: ByteGroup>: BinaryParsable, BinaryWritable, FixedSizeBinary, Hashable, Sendable {
    /// Reserved bytes: there's nothing to say about them.
    @inlinable @inline(__always)
    public init() {}

    /// The reserved bytes' size: `Group.byteCount`.
    @inlinable @inline(__always)
    public static var byteCount: Int { Group.byteCount }

    /// Reads the reserved bytes, checking that they're zero.
    ///
    /// - Parameter reader: The cursor, positioned at the bytes.
    /// - Throws: ``BytesError/insufficientData`` if fewer bytes remain; ``BytesError/invalidValue`` if any
    ///   isn't zero. Nothing is consumed either way.
    @inlinable @inline(__always)
    public init<Mode: BytesCursorMode>(parsing reader: inout GenericBytesReader<Mode>) throws(BytesError) {
        guard try reader.peek(Group.self, .littleEndian) == .zero else { throw .invalidValue }
        try reader.skip(byteCount: Group.byteCount) // Can't throw: the bytes were just read.
    }

    /// Writes the reserved bytes as zeros.
    ///
    /// - Parameter writer: The cursor to write at.
    /// - Throws: ``BytesError/insufficientCapacity`` if there isn't room.
    @inlinable @inline(__always)
    public func write<Mode: BytesCursorMode>(to writer: inout GenericBytesWriter<Mode>) throws(BytesError) {
        try writer.write(Group.Integer.zero, as: Group.self, .littleEndian)
    }
}

public extension GenericBytesReader where Mode: ByteOrderedCursorMode {
    /// Reads a `T` in the cursor's byte order, by its own initializer.
    ///
    /// - Parameter type: The type to read.
    /// - Returns: The value.
    /// - Throws: What `T`'s initializer throws.
    @inlinable @inline(__always)
    @_lifetime(self: copy self)
    mutating func read<T: ByteOrderedParsable>(_ type: T.Type) throws(BytesError) -> T {
        try T(parsing: &self)
    }
}

public extension GenericBytesWriter where Mode: ByteOrderedCursorMode {
    /// Writes `value` in the writer's byte order, by its own method.
    ///
    /// - Parameter value: The value to write.
    /// - Throws: What `value`'s `write(to:)` throws.
    @inlinable @inline(__always)
    @_lifetime(self: copy self)
    mutating func write<T: ByteOrderedWritable>(_ value: T) throws(BytesError) {
        try value.write(to: &self)
    }
}

public extension GenericBytesReader {
    /// Reads a `T`, by its own initializer.
    ///
    /// - Parameter type: The type to read.
    /// - Returns: The value.
    /// - Throws: What `T`'s initializer throws.
    @inlinable @inline(__always)
    @_lifetime(self: copy self)
    mutating func read<T: BinaryParsable>(_ type: T.Type) throws(BytesError) -> T {
        try T(parsing: &self)
    }
}

public extension GenericBytesWriter {
    /// Writes `value`, by its own method.
    ///
    /// - Parameter value: The value to write.
    /// - Throws: What `value`'s `write(to:)` throws.
    @inlinable @inline(__always)
    @_lifetime(self: copy self)
    mutating func write<T: BinaryWritable>(_ value: T) throws(BytesError) {
        try value.write(to: &self)
    }
}
